package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.repository.jobs.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

/** Provisional readonly candidate facts, never a reservation capability. */
class DispatchCandidatePreflightTest {
    SourcePartialDispatchReadinessTest f;
    GenerationJdbcStoreTest database(){return new GenerationJdbcStoreTest();}
    void setup()throws Exception{f=new SourcePartialDispatchReadinessTest(){@Override GenerationJdbcStoreTest database(){return DispatchCandidatePreflightTest.this.database();}};f.setup();}
    <T>T read(java.util.function.Supplier<T> work){var tx=new TransactionTemplate(new DataSourceTransactionManager(f.db.source));tx.setReadOnly(true);return tx.execute(s->work.get());}
    @Test void Actual201MemberPartialOriginalPartsPreflightAndStillNeedSeparateWriterProof()throws Exception{setup();int rows=f.db.count("1=1"),calls=f.db.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class);for(String root:f.roots){assertTrue(read(()->f.service.preflight(root)));var capture=f.service.capturePartial(root);assertTrue(f.ready(root,capture));assertThrows(RuntimeException.class,()->f.db.writes.execute(new SharedWriteExecutor.ActionContext("fictional-preflight-is-not-permission",root,null),k->null,c->f.service.ready(root)));}assertEquals(rows,f.db.count("1=1"));assertEquals(calls,f.db.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class));assertEquals(0,f.db.count("target_type IN ('worker_claim','worker_send')"));}
    @Test void MemberRevisionIsCurrentButOriginalAttemptRequestStillMustBeCheckedInWriter()throws Exception{setup();String root=f.roots.getFirst(),member=f.plan.chunks().getFirst().itemIds().getFirst();var capture=f.service.capturePartial(root);f.db.jdbc.update("UPDATE source_run_items SET revision=revision+1 WHERE id=?",member);assertFalse(read(()->f.service.preflight(root)));assertFalse(f.ready(root,capture));f.db.jdbc.update("UPDATE source_run_items SET revision=revision-1 WHERE id=?",member);String request=f.db.jdbc.queryForObject("SELECT request_json FROM jobs WHERE root_job_id=? AND record_kind='ai_attempt'",String.class,root);f.db.jdbc.update("UPDATE jobs SET request_json=? WHERE root_job_id=? AND record_kind='ai_attempt'",request.replace("deepseek-flash","fictional-changed-model"),root);assertTrue(read(()->f.service.preflight(root)));assertThrows(RuntimeException.class,()->f.ready(root,capture));assertEquals(0,new JdbcJobRecords(f.db.source).byId(root).callCount());assertEquals(0,f.db.count("target_type='worker_claim'"));}
    @Test void RoleDefaultPermitAndChangedNativeP1NeverGrantWriterAuthority()throws Exception{setup();String root=f.roots.getFirst();var capture=f.service.capturePartial(root);assertThrows(RuntimeException.class,()->f.service.preflight(root));assertThrows(RuntimeException.class,()->f.q.q.h.f.p1.tx(()->f.service.preflight(root)));assertThrows(RuntimeException.class,()->read(()->f.service.readyPartial(root,capture)));f.service=f.provider(null);assertTrue(read(()->f.service.preflight(root)));assertThrows(RuntimeException.class,()->f.service.capturePartial(root));assertThrows(RuntimeException.class,()->f.ready(root,capture));f.service=f.provider(f.q.q.a.service);String p1=f.q.q.a.f.plan.chunks().getLast().rootId();f.db.jdbc.update("UPDATE jobs SET revision=revision+1 WHERE id=?",p1);assertThrows(RuntimeException.class,()->read(()->f.service.preflight(root)));assertEquals(0,f.db.count("target_type='worker_send'"));}
    @Test void NonSourceOriginalIdentityReferencesAndLatestRemainRequired(){var legacy=new DispatchReadinessServiceTest(){@Override GenerationJdbcStoreTest fixture(){return DispatchCandidatePreflightTest.this.database();}};legacy.setup();legacy.prepare(GenerationFlowService.Stage.AD_HOC_AI);var tx=new TransactionTemplate(new DataSourceTransactionManager(legacy.f.source));tx.setReadOnly(true);assertEquals(Boolean.TRUE,tx.execute(s->legacy.service.preflight(legacy.f.OWNER)));legacy.references=false;assertEquals(Boolean.FALSE,tx.execute(s->legacy.service.preflight(legacy.f.OWNER)));legacy.references=true;legacy.f.jdbc.update("DELETE FROM jobs WHERE target_type='generation_lineage'");assertThrows(RuntimeException.class,()->tx.execute(s->legacy.service.preflight(legacy.f.OWNER)));assertEquals(0,legacy.f.count("target_type='worker_send'"));}
}
